using Microsoft.ML;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

builder.Services.AddSingleton<ModelTrainingService>();
var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

// Train and save the model, then extract ordered label names from the schema
var trainer = app.Services.GetRequiredService<ModelTrainingService>();
trainer.TrainAndSave();

var mlContext = new MLContext();
var model = mlContext.Model.Load(modelPath, out var schema);
var labelColumn = model.GetOutputSchema(schema)["Score"];
var slotNames = new VBuffer<ReadOnlyMemory<char>>();
labelColumn.GetSlotNames(ref slotNames);
var labels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
builder = null; // not reused

// Register the label ordering so the controller maps scores correctly
app.Services.GetRequiredService<IConfiguration>()["ModelLabels"] = string.Join(",", labels);

app.MapControllers();
app.Run();

